def transform(grid):
    output = []
    for row in grid:
        if len(set(row)) <= 1:
            output.append(row[:])
        else:
            seen_colors = []
            boundary_col = len(row)
            for i, c in enumerate(row):
                if c not in seen_colors:
                    boundary_col = i
                    seen_colors.append(c)
            new_row = row[:boundary_col] + [1] * (len(row) - boundary_col)
            output.append(new_row)
    return output

