def is_alternating(row, skip_seq=1):
    """Check if row is alternating (A B A B A B...) after skip_seq violations"""
    if len(row) < 2:
        return True
    pattern = row[:skip_seq]
    found_types = list(set(pattern))
    if len(found_types) > 2:
        return False
    # After skip_seq, check alternating
    for i in range(skip_seq, len(row)-1):
        expected_indices = [(i - skip_seq) % 2, (i - skip_seq + 1) % 2]
        for exp_idx in expected_indices:
            pattern_idx = skip_seq + exp_idx
            if pattern_idx < len(pattern) and row[i] != pattern[pattern_idx]:
                return False
    return True

